                        }
                        addState(ns, ways);                    // 把新状态加入下一轮
                    }
                }

                cur[s] = 0;                                    // 当前状态处理完，清零以复用数组
            }

            curList.swap(nxtList);                             // 进入下一格时，当前状态变成刚转移出的状态
            swap(cur, nxt);                                    // 交换 cur / nxt 的角色
        }
