const int MAXN=1e5+5;
const int LOG=20; // 2^20>1e6，足够大多数情况
vector<int> G[MAXN];
int depth[MAXN], up[LOG][MAXN];

// 预处理倍增数组
void dfs(int u, int father) {
    up[0][u]=father;
    depth[u]=depth[father]+1;
    // 预处理2^1到2^(LOG-1)级祖先
    for(int k=1;k<LOG;k++) {
        up[k][u]=up[k-1][up[k-1][u]];
    }
    for(int v:G[u]) {
        if(v!=father) dfs(v,u);
    }
}

// 倍增求LCA
int lca(int u, int v) {
    // 让u成为深度更大的节点
    if(depth[u]<depth[v]) swap(u,v);
    // u向上跳到和v同深度
    int diff=depth[u]-depth[v];
    for(int k=0;k<LOG;k++) {
        if(diff&(1<<k)) {
            u=up[k][u];
        }
    }
    if(u==v) return u;
    // 从大到小枚举k，跳尽可能大的步长
    for(int k=LOG-1;k>=0;k--) {
        if(up[k][u]!=up[k][v]) {
            u=up[k][u];
            v=up[k][v];
        }
    }
    // 最后父节点就是LCA
    return up[0][u];
}
```

