```cpp迭代法求lca
#include<bits/stdc++.h>
using namespace std;

const int N = 3e5 + 10;
const int LOG = 20; // 2^19 > 3e5，所以 0~19 足够

struct Edge {
    int to;
    int w;
};

vector<Edge> g[N];

int n, m;
int depth[N];
int fa[N][LOG];
long long distRoot[N]; // 如果不需要距离，可以删掉

void build_lca_iterative(int root = 1)
{
    vector<int> order;
    order.reserve(n);

    stack<int> st;
    st.push(root);

    fa[root][0] = 0;
    depth[root] = 1;
    distRoot[root] = 0;

    while (!st.empty())
    {
        int u = st.top();
        st.pop();

        order.push_back(u);

        for (auto e : g[u])
        {
            int v = e.to;
            int w = e.w;

            if (v == fa[u][0]) continue;

            fa[v][0] = u;
            depth[v] = depth[u] + 1;
            distRoot[v] = distRoot[u] + w;

            st.push(v);
        }
    }

    for (int j = 1; j < LOG; j++)
    {
        for (int i = 1; i <= n; i++)
        {
            fa[i][j] = fa[fa[i][j - 1]][j - 1];
        }
    }
}

int lca(int x, int y)
{
    if (depth[x] < depth[y])
    {
        swap(x, y);
    }

    int diff = depth[x] - depth[y];

    for (int j = LOG - 1; j >= 0; j--)
    {
        if ((diff >> j) & 1)
        {
            x = fa[x][j];
        }
    }

    if (x == y) return x;

    for (int j = LOG - 1; j >= 0; j--)
    {
        if (fa[x][j] != fa[y][j])
        {
            x = fa[x][j];
            y = fa[y][j];
        }
    }

    return fa[x][0];
}

long long get_dist(int u, int v)
{
    int g = lca(u, v);
    return distRoot[u] + distRoot[v] - 2LL * distRoot[g];
}
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;

    for (int i = 1; i < n; i++)
    {
        int u, v, w;
        cin >> u >> v >> w;

        g[u].push_back({v, w});
        g[v].push_back({u, w});
    }

    build_lca_iterative(1);

    while (m--)
    {
        int u, v;
        cin >> u >> v;

        cout << lca(u, v) << '\n';
        // 如果要求距离：
        // cout << get_dist(u, v) << '\n';
    }

    return 0;
}
