## P3258 [JLOI2014] 松鼠的新家

**题意概要**：给定一棵有 $n$ 个节点的树和一个访问序列 $a_1, a_2, \dots, a_n$（其实 $a$ 是个排列）。松鼠从 $a_1$ 依次走到 $a_2, a_3, \dots, a_n$，每经过一个节点（包括路径上的中间节点和到达的终点）时可以拿一颗糖果。要求计算保证松鼠每次到达都能拿到糖果的前提下，每个房间（节点）需要准备多少糖果。注意，最后一次到达 $a_n$ 时不取糖果（因为那里是宴会）。输出每个节点需要准备的糖果数。

**解题思路**：其实此题等价于：对于序列中连续的节点对 $(a_i, a_{i+1})$（$1 \le i < n$），都加上1
```cpp
#include<bits/stdc++.h>

using namespace std;

int n;

const int N=3e5+10;

int fa[N][20];

int depth[N];

vector<int>adj[N];

int val[N];

int arr[N];

int log2(int x)

{

    int res=-1;

    while(x)

    {

        x=x>>1;

        res++;

    }

    return res;

}

void dfs(int rt,int rf)

{

    depth[rt]=depth[rf]+1;

    fa[rt][0]=rf;

    for(int i=0;i<adj[rt].size();i++)

    {

        if(adj[rt][i]!=rf)

        {

            dfs(adj[rt][i],rt);

        }

    }

}

int lca(int x,int y)

{

    if(depth[x]<depth[y])

    {

        swap(x,y);

    }

    for(int i=log2(depth[x]-depth[y]);i>=0;i--)

    {

        if(depth[fa[x][i]]>=depth[y])

        {

            x=fa[x][i];

        }

    }

    if(x==y)

    return x;

    for(int i=log2(depth[x]);i>=0;i--)

    {

        if(fa[x][i]!=fa[y][i])

        {

            x=fa[x][i];

            y=fa[y][i];

        }

    }

    return fa[x][0];

}

void dfs1(int s,int t)

{

    val[s]++;

    val[t]++;

    int pa=lca(s,t);

    val[pa]--;

    val[fa[pa][0]]--;

}

void dfs2(int rt,int rf)

{

    for(int i=0;i<adj[rt].size();i++)

    {

        if(adj[rt][i]!=rf)

        {

            dfs2(adj[rt][i],rt);

            val[rt]+=val[adj[rt][i]];

        }

    }

}

int main()

{

    cin>>n;

    for(int i=1;i<=n;i++)

    {

        cin>>arr[i];

    }

    for(int i=1;i<n;i++)

    {

        int x,y;

        cin>>x>>y;

        adj[x].push_back(y);//这里x存的是a_i的编号

        adj[y].push_back(x);

    }

    dfs(arr[1],0);

    for(int j=1;j<20;j++)

    {

        for(int i=1;i<=n;i++)

        {

            fa[i][j]=fa[fa[i][j-1]][j-1];

        }

    }

    for(int i=1;i<n;i++)

    {

        dfs1(arr[i],arr[i+1]);

        // cout<<arr[i]<<" "<<fa[arr[i+1]][0]<<endl;

    }

    dfs2(arr[1],0);

    for(int i=2;i<=n;i++)

    {

        val[arr[i]]--;

    }

    for(int i=1;i<=n;i++)

    {

        cout<<val[i]<<endl;

    }

}
```

