            // 退出事件最后执行
            st.push({2, u, 0});

            // 倒序压栈，让遍历顺序接近递归 DFS
            for (int i = (int)g[u].size() - 1; i >= 0; i--)
            {
                int to = g[u][i].to;
                int w = g[u][i].w;

                if (to == v) continue;

                distRoot[to] = distRoot[u] + w;

                // 先压合并，再压进入
                // 因为栈后进先出，所以会先处理子树，再合并
                st.push({1, u, to});
                st.push({0, to, u});
            }
        }
        else if (type == 1)
        {
            // 子树 v 已经处理完，合并 u 和 v
            int fu = findset(u);
            int fv = findset(v);

            dsu[fv] = fu;
            ancestor[fu] = u;
        }
        else
        {
            // 退出节点 u，标记为访问完成
            vis[u] = true;

            for (auto item : q[u])
            {
                int other = item.to;
                int id = item.id;

                if (vis[other])
                {
                    ansLca[id] = ancestor[findset(other)];
                }
            }
        }
    }
}

long long get_dist_by_lca(int u, int v, int lca)
{
    return distRoot[u] + distRoot[v] - 2LL * distRoot[lca];
}
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;

    for (int i = 1; i < n; i++)
    {
        int u, v, w;
        cin >> u >> v >> w;

        g[u].push_back({v, w});
        g[v].push_back({u, w});
    }

    vector<pair<int, int>> ask(m + 1);

    for (int i = 1; i <= m; i++)
    {
        int u, v;
        cin >> u >> v;

        ask[i] = {u, v};

        q[u].push_back({v, i});
        q[v].push_back({u, i});
    }

    tarjan_lca_iterative(1);

    for (int i = 1; i <= m; i++)
    {
        int u = ask[i].first;
        int v = ask[i].second;
        int g = ansLca[i];

        cout << "LCA = " << g << '\n';

        // 如果要求路径距离：
        // cout << get_dist_by_lca(u, v, g) << '\n';
    }

    return 0;
}
