    {

        cin>>arr[i];

    }

    for(int i=1;i<n;i++)

    {

        int x,y;

        cin>>x>>y;

        adj[x].push_back(y);//这里x存的是a_i的编号

        adj[y].push_back(x);

    }

    dfs(arr[1],0);

    for(int j=1;j<20;j++)

    {

        for(int i=1;i<=n;i++)

        {

            fa[i][j]=fa[fa[i][j-1]][j-1];

