#include<bits/stdc++.h>
using namespace std;

int n, k;
const int N = 5e4 + 10;
int fa[N][18];
int depth[N];
vector<int> adj[N];
int val[N];

// 顺手优化：用更直观的移位来算 log2
int get_log(int x) {
    int res = 0;
    while ((1 << (res + 1)) <= x) res++;
    return res;
}

void dfs(int rt, int rf) {
    depth[rt] = depth[rf] + 1;
    fa[rt][0] = rf;
    for (int i = 0; i < adj[rt].size(); i++) {
        if (adj[rt][i] != rf) {
            dfs(adj[rt][i], rt);
        }
    }
}

int lca(int x, int y) {
    if (depth[x] < depth[y]) {
        swap(x, y);
    }

    // 修正：让 x 向上跳到与 y 同一深度
    for (int i = 17; i >= 0; i--) {
        if (depth[fa[x][i]] >= depth[y]) {
            x = fa[x][i];
        }
    }

    if (x == y) return x;

    // 两个一起向上跳
    for (int i = 17; i >= 0; i--) {
        if (fa[x][i] != fa[y][i]) {
            x = fa[x][i];
            y = fa[y][i];
        }
    }
    return fa[x][0];
}

void dfs1(int s, int t) {
    val[s]++;
    val[t]++;
    int pa = lca(s, t);
    val[pa]--;
    val[fa[pa][0]]--; // 父亲的父亲减一，完美符合树上点差分
}

int maxcnt = 0;
void dfs2(int rt, int rf) {
    for (int i = 0; i < adj[rt].size(); i++) {
        if (adj[rt][i] != rf) {
            dfs2(adj[rt][i], rt); // 修正 1：这里必须调用 dfs2，而不是 dfs
            val[rt] += val[adj[rt][i]];
        }
    }
    maxcnt = max(maxcnt, val[rt]);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr); // 顺手加个快读加速

    cin >> n >> k;
    for (int i = 1; i < n; i++) {
        int x, y;
        cin >> x >> y;
        adj[x].push_back(y);
        adj[y].push_back(x);
    }

    depth[0] = 0; // 哨兵节点初始化
    dfs(1, 0);

    // 预处理倍增数组
    for (int j = 1; j <= 17; j++) {
        for (int i = 1; i <= n; i++) {
            fa[i][j] = fa[fa[i][j-1]][j-1];
        }
    }

    for (int i = 1; i <= k; i++) {
        int s, t;
        cin >> s >> t;
        dfs1(s, t);
    }

    dfs2(1, 0); // 修正 2：必须在最后调用 dfs2 汇总差分结果！

    cout << maxcnt << endl;
    return 0;
}
