vector<int>res;
int kinds[N];//每种种类的个数 肯定>=1
bool check(int k)
{
    int left1=0;
    int cur=1;
    res.clear();
    for(int i=1;i<=tok;i++)
    {
        for(int j=cur+min(kinds[i]-1,k-left1-1);j>=cur;j--)
        {
            int nowb=person[j].b;
            if(left1+j-cur+1+nowb>=k)
            {
                left1=left1+j-cur+1;
                for(int u=j;u>=cur;u--)
                {
                    res.push_back(person[u].id);
                }
                break;
            }
        }
        cur=cur+kinds[i];
    }
    if(left1>=k)
    return 1;
    else
    return 0;
}
